long long selecao(vector<int> v) {
    long long comp = 0;
    int n = v.size();
    for (int i = 0; i < n - 1; i++) {
        int iMenor = i;
        for (int j = i + 1; j < n; j++) {
            comp++;
            if (v[j] < v[iMenor]) iMenor = j;
        }
        swap(v[i], v[iMenor]);
    }
    return comp;
}

long long bolha(vector<int> v) {
    long long comp = 0;
    int n = v.size();
    for (int fim = n - 1; fim > 0; fim--) {
        bool trocou = false;
        for (int j = 0; j < fim; j++) {
            comp++;
            if (v[j] > v[j + 1]) {
                swap(v[j], v[j + 1]);
                trocou = true;
            }
        }
        if (!trocou) break;
    }
    return comp;
}

long long insercao(vector<int> v) {
    long long comp = 0;
    int n = v.size();
    for (int i = 1; i < n; i++) {
        int atual = v[i];
        int j = i - 1;
        while (j >= 0) {
            comp++;
            if (v[j] <= atual) break;
            v[j + 1] = v[j];
            j--;
        }
        v[j + 1] = atual;
    }
    return comp;
}

